e\": \"text\"}, {\"bbox\": [{\"coord\": [244, 1747, 801, 1832], \"page_id\": 75}], \"content\": \"Total U.S. banking liabilities to foreigners, which expanded $104 billion in 1995, rose just $1.2 billion in the first quarter of 1996. This small net increase is\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 1494, 1393, 1664], \"page_id\": 75}], \"content\": \"the result of offsetting changes in liabilities to different regions: U.S. liabilities to foreigners in the United Kingdom, other Europe, and Japan increased $15.9 billion as of March 1996, while liabilities to the Caribbean banking centers, other Asia, and \\\"All other countries\\\" declined by $14.8 billion.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1662, 1392, 1836], \"page_id\": 75}], \"content\": \"By region, the direction and magnitude of changes in U.S. banking liabilities in the first quarter were varied. The largest change was the $8.1 billion increase in liabilities to Japan, which continued a long upward trend and resulted in a new high of $148.3 billion.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 87, 169, 113], \"page_id\": 76}], \"content\": \"74\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [667, 85, 962, 111], \"page_id\": 76}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [200, 193, 1430, 233], \"page_id\": 76}], \"content\": \"SECTION II.\\u2014Claims on Foreigners Reported by Banks in the United States\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [530, 255, 1096, 288], \"page_id\": 76}], \"content\": \"TABLE CM-II-1.\\u2014Total Claims by Type\", \"description\": null, \"id\": 3, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [477, 309, 1149, 332], \"page_id\": 76}], \"content\": \"[Position at e